{% for article in articles %}

  https://ombradelportico.it{% url 'dettaglio_articolo' article.slug %}
  {{ article.data_pubblicazione|date:"c" }}
  {% if article.days_old < 7 %}daily{% elif article.days_old < 30 %}weekly{% else %}monthly{% endif %}
  {% if article.days_old < 1 %}0.9{% elif article.days_old < 7 %}0.7{% elif article.days_old < 30 %}0.5{% else %}0.3{% endif %}

{% endfor %}
